const r = await tools.exec_command({
  cmd: "python - <<'PY'
from pathlib import Path
import pandas as pd
from collections import defaultdict
G=defaultdict(list)
for p in Path('.').glob('*.csv'):
    stem=p.stem.rsplit('_',1)[0]
    G[stem].append(p)
for stem, ps in sorted(G.items()):
    counts=[]
    for p in sorted(ps):
        with open(p,'rb') as f: n=sum(1 for _ in f)-1
        counts.append(n)
    d=pd.read_csv(sorted(ps)[0],nrows=0)
    print(f'{stem:20s} files={len(ps):2d} rows={sum(counts):9d} monthly={counts} cols={list(d.columns)}')
PY",
  workdir: "/app",
  yield_time_ms: 10000,
  max_output_tokens: 20000
});
text(r.output);

